  "bots.setup.callbackUrlDescription.webhook":
    "Votre système externe doit envoyer les rappels des messages entrants à cette adresse. Les réponses sortantes asynchrones utilisent toujours l’URL de webhook saisie à gauche.",
  "bots.setup.callbackUrlDescription.webhookBind":
    "La liaison par webhook utilise le même point de terminaison : envoyez ici une requête de rappel privée avec text = /bind <code>.",
  "bots.setup.guide.telegram.create.1": "Ouvrez @BotFather dans Telegram et créez un nouveau bot.",
  "bots.setup.guide.telegram.create.2":
    "Copiez le jeton d’API HTTP renvoyé par BotFather et collez-le dans ce formulaire.",
  "bots.setup.guide.telegram.create.3":
    "Il est utile d’ouvrir dès maintenant la discussion privée du bot, car la commande de liaison doit y être envoyée.",
