  "bots.setup.guide.weixin.bind.3":
    "Revenez ici après la réussite de la liaison pour terminer les valeurs par défaut de l’espace de travail et de la CLI.",
  "bots.setup.guide.feishu.create.1":
    "Créez une application personnalisée dans la console développeur Feishu/Lark et activez la fonctionnalité de bot.",
  "bots.setup.guide.feishu.create.2":
    "Copiez l’ID d’application et le secret d’application, puis activez les événements de connexion persistante pour `im.message.receive_v1` et les actions de carte.",
  "bots.setup.guide.feishu.create.3":
    "Choisissez ici le domaine Feishu ou Lark correspondant, puis collez les identifiants dans le formulaire.",
  "bots.setup.guide.feishu.bind.1":
    "Installez l’application dans votre organisation et ouvrez une discussion directe avec le bot.",
