  "settings.modelProvider.help.contextWindow":
    "Capacité de contexte que le modèle peut traiter en une fois, en jetons. DeepVibe s’en sert pour gérer le contexte.\nNe dépassez pas la limite réelle du modèle.",
  "settings.modelProvider.help.maxOutputTokens":
    "Nombre maximal de jetons qu’une requête unique au modèle peut générer.\nNe dépassez pas la limite réelle du modèle.",
  "settings.modelProvider.help.inputModalities":
    "Définissez les types de contenu que le modèle peut recevoir :\n\n- **Texte** : reçoit du contenu textuel. Obligatoire.\n- **Images** : reçoit du contenu image.\n- **Vidéo** : reçoit du contenu vidéo.\n- **PDF** : reçoit directement des documents PDF.",
  "settings.modelProvider.help.outputModalities":
    "Type de contenu des réponses du modèle. Seul le texte est pris en charge actuellement.",
  "settings.modelProvider.help.capabilities":
    "- **Sortie structurée** : prend en charge les contraintes JSON Schema sur les champs, les types et la structure de sortie.\n- **Recherche web native** : prend en charge la fonction de recherche web intégrée à l’API du modèle.\n- **Messages système en cours de conversation** : permet d’insérer des instructions système pendant une conversation.\n\nN’activez pas de capacités que le modèle ne prend pas en charge.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "Définissez les niveaux de raisonnement disponibles dans le chat. **Ils doivent être classés du plus faible au plus élevé en effort de raisonnement**.\nNe configurez pas de niveaux de raisonnement que le modèle ne prend pas en charge.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "Utilisez une expression CEL pour faire correspondre le niveau de raisonnement actuel, `reasoningLevel`, aux champs de la requête envoyée à l’API du modèle. L’objet JSON renvoyé par l’expression est fusionné dans le corps de la requête sortante.",
  "settings.modelProvider.help.advanced":
    "**Schéma d’outil MFJS** : active la compatibilité Moonshot Flavored JSON Schema, couramment utilisée par l’API du modèle Kimi de Moonshot. Activez cette option uniquement si l’API du modèle exige ce format.",
  "settings.modelProvider.help.followRecommendedConfig":
    "Fait correspondre la configuration recommandée à partir de l’ID du modèle, de l’URL de base et du format d’API. DeepVibe met continuellement à jour les recommandations et les synchronise automatiquement pour vous.\nLorsque vous modifiez manuellement un paramètre, celui-ci passe en gestion manuelle et cesse de suivre les mises à jour des recommandations ; les autres paramètres restent gérés par la configuration intelligente.",
